CREATE TABLE "public"."album_status" (
  "id"          bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at"  timestamp with time zone NOT NULL DEFAULT now(),
  "album_id"    bigint,
  "is_active"   boolean                  DEFAULT false,
  "active_date" date                     DEFAULT CURRENT_DATE,           
  CONSTRAINT "album_status_album_id_key" UNIQUE (album_id),
  CONSTRAINT "album_status_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."album_status"
  ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE "public"."album_status" FROM "authenticated";

ALTER TABLE "public"."album_status"
  ADD CONSTRAINT "album_status_album_id_fkey" FOREIGN KEY (album_id) REFERENCES public.albums(id) ON DELETE CASCADE;

